import {Renderer,drawCar} from './render.js';
import {activeLanguage,drawLocalizedText} from './i18n.js';
import {signalPhase} from './traffic.js';
import {lerp,TAU,distance} from './math.js';
const inScene=(o,b,m=80)=>o.x+(o.w||m)>b.x&&o.y+(o.h||m)>b.y&&o.x-m<b.x+b.w&&o.y-m<b.y+b.h;
function paintPolygon(c,poly){c.beginPath();poly.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();}
const classicWorldDraw=Renderer.prototype.drawWorld,classicMapDraw=Renderer.prototype.drawMap;
Renderer.prototype.drawWorld=function(c,b){if(this.sim.world.mapKind!=='real'){classicWorldDraw.call(this,c,b);this.drawVenues(c,b);return;}const w=this.sim.world;c.fillStyle='#878677';c.fillRect(0,0,w.size,w.size);for(const water of w.water){c.fillStyle='#244f5b';paintPolygon(c,water.poly);c.fill();c.strokeStyle='#b7b89d';c.lineWidth=9;c.stroke();}c.lineCap='butt';for(const building of w.buildings){if(!inScene(building,b))continue;c.save();c.translate(7,9);c.fillStyle='#182b2555';paintPolygon(c,building.poly);c.fill();c.restore();c.fillStyle=building.color;paintPolygon(c,building.poly);c.fill();c.strokeStyle='#d3cdb955';c.lineWidth=2;c.stroke();this.drawUrbanRoof(c,building);if(building.w>45&&building.h>45){c.fillStyle='#556b6466';c.fillRect(building.x+building.w*.4,building.y+building.h*.4,Math.min(25,building.w*.25),Math.min(18,building.h*.25));}}this.drawRealRoads(c,b);for(const prop of w.streetProps||[])if(inScene(prop,b,90))this.drawUrbanProp(c,prop);for(const n of w.signals||[]){if(!inScene(n,b))continue;const phase=signalPhase(this.sim.time,n.i,n.j);for(const [axis,dx,dy] of [['ew',-28,-28],['ns',28,28]]){c.fillStyle='#263c34';c.fillRect(n.x+dx-6,n.y+dy-13,12,26);c.fillStyle=phase[axis]==='green'?'#8cc993':phase[axis]==='amber'?'#e8c26c':'#e87260';c.beginPath();c.arc(n.x+dx,n.y+dy,4,0,TAU);c.fill();}}this.drawVenues(c,b);let labels=0;const labelNames=new Set(),labelPoints=[];c.font='11px Arial';c.textAlign='center';for(const road of w.roads){if(!road.name||road.walk||labelNames.has(road.name)||labels>=5)continue;const q=road.points[Math.floor(road.points.length/2)];if(!inScene({x:q[1],y:q[2]},b,0)||labelPoints.some(p=>distance(p,{x:q[1],y:q[2]})<190))continue;labelNames.add(road.name);labelPoints.push({x:q[1],y:q[2]});c.fillStyle='#e3dfc7aa';drawLocalizedText(c,road.name,q[1],q[2]-10);labels++;}};
Renderer.prototype.drawVenues=function(c,b){for(const l of this.sim.world.locations||[]){if(!inScene(l,b,110))continue;const target=this.sim.story?.target(),active=target?.id===l.id;c.fillStyle=active?'#eea25b':'#c5c8ab';c.beginPath();c.arc(l.x,l.y,active?22:15,0,TAU);c.fill();c.fillStyle='#22362e';c.font='bold 18px Arial';c.textAlign='center';c.fillText(l.kind==='restaurant'?'♨':l.kind==='home'?'⌂':l.kind==='garage'?'⚒':'E',l.x,l.y+6);c.fillStyle=active?'#ffe0a4':'#d8d9bb';c.font='bold 11px Arial';drawLocalizedText(c,l.name,l.x,l.y-32);if(active){c.strokeStyle='#f4b46d';c.setLineDash([8,7]);c.lineWidth=2;c.beginPath();c.arc(l.x,l.y,52+Math.sin(this.sim.time*3)*6,0,TAU);c.stroke();c.setLineDash([]);}}};
Renderer.prototype.drawPeople=function(c,b){const s=this.sim,h=s.human;if(!h)return;for(const a of [...h.people,...(h.onFoot?[h.avatar]:[])]){if(a.scene!==h.scene()||!inScene(a,b,35))continue;c.save();c.translate(a.x,a.y);c.rotate(a.angle);if(!a.alive){c.globalAlpha=Math.min(.6,a.death/4);c.fillStyle='#38433d';c.fillRect(-13,-7,26,14);c.restore();continue;}c.fillStyle='#0d21194d';c.beginPath();c.ellipse(3,5,13,10,0,0,TAU);c.fill();const stride=Math.sin(s.time*(a.kind==='ped'?7:12))*3*(a===h.avatar?a.speed/155:1);c.fillStyle='#202b30';c.fillRect(-8,-7+stride,9,5);c.fillRect(-8,3-stride,9,5);c.fillStyle=a.hit>0?'#f7e6ba':a.kind==='swat'?'#293c4d':a.kind==='officer'?'#57798b':a.kind==='mafia'?'#54434a':a.color;c.beginPath();c.ellipse(0,0,9,12,0,0,TAU);c.fill();c.fillStyle=a.kind==='swat'?'#182d39':'#c5aa88';c.beginPath();c.arc(1,0,6,0,TAU);c.fill();if(a.kind==='swat'){c.fillStyle='#84989f';c.fillRect(3,-5,3,10);c.fillStyle='#111e28';c.fillRect(-8,-8,6,16);}if(a.kind!=='ped'){c.fillStyle='#c4af91';c.fillRect(5,3,11,4);c.fillStyle='#243336';c.fillRect(12,2,a.weapon==='carbine'?19:12,4);}c.restore();if(a.kind==='swat'||a.kind==='mafia'&&a.maxHp>150){c.fillStyle='#102421';c.fillRect(a.x-17,a.y-21,34,4);c.fillStyle=a.kind==='swat'?'#75abc8':'#dc916d';c.fillRect(a.x-17,a.y-21,34*a.hp/a.maxHp,4);}}for(const shot of h.bullets){if(shot.scene!==h.scene())continue;c.strokeStyle=shot.owner==='player'?'#ffe2a1':'#db9e7b';c.lineWidth=shot.owner==='player'?2:1.3;c.beginPath();c.moveTo(shot.px,shot.py);c.lineTo(shot.x,shot.y);c.stroke();}if(h.onFoot){const a=h.avatar;c.strokeStyle='#d9dbbc88';c.lineWidth=1;c.beginPath();c.moveTo(a.x+Math.cos(a.angle)*30,a.y+Math.sin(a.angle)*30);c.lineTo(a.x+Math.cos(a.angle)*48,a.y+Math.sin(a.angle)*48);c.stroke();}};
Renderer.prototype.renderInterior=function(dt){const s=this.sim,h=s.human,p=s.player,c=this.ctx,room=h.interior,z=this.w<600?.65:.9;this.camera.zoom=lerp(this.camera.zoom,z,Math.min(1,dt*7));this.camera.x=lerp(this.camera.x,p.x,Math.min(1,dt*8));this.camera.y=lerp(this.camera.y,p.y,Math.min(1,dt*8));c.setTransform(this.ratio,0,0,this.ratio,0,0);c.fillStyle='#101b1b';c.fillRect(0,0,this.w,this.h);c.save();c.translate(this.w/2,this.h/2);c.scale(this.camera.zoom,this.camera.zoom);c.translate(-this.camera.x,-this.camera.y);c.fillStyle=room.location.kind==='club'?'#555164':'#9b886c';c.fillRect(90,80,920,670);c.strokeStyle='#2b362831';c.lineWidth=1;for(let x=90;x<1010;x+=55){c.beginPath();c.moveTo(x,80);c.lineTo(x,750);c.stroke();}for(let y=80;y<750;y+=50){c.beginPath();c.moveTo(90,y);c.lineTo(1010,y);c.stroke();}for(const o of room.world.buildings){c.fillStyle=o.kind==='wall'?'#424f49':o.kind==='table'?'#746342':o.kind==='crate'?'#727659':o.kind==='bed'?'#a8b6b3':'#666e5e';c.fillRect(o.x,o.y,o.w,o.h);c.strokeStyle='#d3cbb080';c.lineWidth=3;c.strokeRect(o.x,o.y,o.w,o.h);if(o.kind==='table'){c.fillStyle='#d7d4ba';c.beginPath();c.arc(o.x+o.w*.35,o.y+o.h*.45,10,0,TAU);c.fill();}}c.fillStyle='#a3c39c';c.fillRect(470,723,160,24);c.font='bold 15px Arial';c.textAlign='center';c.fillStyle='#eff0d0';drawLocalizedText(c,activeLanguage==='en'?'EXIT · E':'ÇIKIŞ · E',550,711);c.font='bold 23px Arial';drawLocalizedText(c,room.location.name,550,145);this.drawPeople(c,{x:0,y:0,w:1100,h:1100});c.restore();};
Renderer.prototype.drawMap=function(canvas,full=false){const s=this.sim,h=s.human;if(s.world.mapKind!=='real'&&!h?.interior){classicMapDraw.call(this,canvas,full);return;}const c=canvas.getContext('2d'),W=canvas.width,H=canvas.height,w=h?.interior?.world||s.world,p=s.player,scale=full?W/w.size:W/(h?.interior?1100:1900);c.fillStyle='#1c332d';c.fillRect(0,0,W,H);c.save();if(!full)c.translate(W/2-p.x*scale,H/2-p.y*scale);c.scale(scale,scale);if(h?.interior){c.fillStyle='#7b8066';for(const o of w.buildings)c.fillRect(o.x,o.y,o.w,o.h);}else{for(const water of w.water){c.fillStyle='#254f5e';paintPolygon(c,water.poly);c.fill();}c.strokeStyle='#849487';c.lineCap='round';for(const r of w.roads){if(r.walk)continue;if(!full&&r.points.every(q=>distance({x:q[1],y:q[2]},p)>1700))continue;c.lineWidth=Math.max(r.width,full?14:20);c.beginPath();r.points.forEach((q,i)=>i?c.lineTo(q[1],q[2]):c.moveTo(q[1],q[2]));c.stroke();}for(const cover of w.covers){c.fillStyle='#8dadb9aa';if(cover.poly){paintPolygon(c,cover.poly);c.fill();}else c.fillRect(cover.x,cover.y,cover.w,cover.h);}for(const l of w.locations){c.fillStyle=s.story?.target()?.id===l.id?'#f4ad6e':'#b5d0a3';c.beginPath();c.arc(l.x,l.y,(full?4:3)/scale,0,TAU);c.fill();if(full){c.font='bold '+9/scale+'px Arial';c.textAlign='center';drawLocalizedText(c,l.name,l.x,l.y-8/scale);}}for(const cop of s.cops){c.fillStyle=cop.swat?'#82bdd5':'#e57d6c';c.beginPath();c.arc(cop.x,cop.y,3.5/scale,0,TAU);c.fill();}if(s.heli.active){c.strokeStyle='#dec17888';c.lineWidth=1/scale;c.beginPath();c.arc(s.heli.x,s.heli.y,s.heli.radius,0,TAU);c.stroke();}if(s.waypoint){c.strokeStyle='#eeab71';c.lineWidth=2/scale;c.beginPath();c.moveTo(p.x,p.y);for(const q of s.navRoute||[])c.lineTo(q.x,q.y);c.stroke();}}c.fillStyle='#f98a52';c.beginPath();c.arc(p.x,p.y,4/scale,0,TAU);c.fill();c.restore();if(full&&!h?.interior){c.fillStyle='#cad2bc';c.font='9px Arial';c.textAlign='left';c.fillText('© OpenStreetMap contributors · ODbL 1.0',8,H-8);}};

Renderer.prototype.drawUrbanRoof=function(c,b){
 const seed=Math.abs(Number(b.id)||Math.round(b.x*7+b.y)),kind=seed%7;
 c.save();paintPolygon(c,b.poly);c.clip();
 if(kind<3){c.fillStyle=['#8c6554','#a17560','#795f50'][kind];c.fillRect(b.x,b.y,b.w,b.h);c.strokeStyle='#d2a08440';c.lineWidth=1;for(let y=b.y+4;y<b.y+b.h;y+=9){c.beginPath();c.moveTo(b.x,y);c.lineTo(b.x+b.w,y);c.stroke();}for(let x=b.x+7;x<b.x+b.w;x+=15){c.beginPath();c.moveTo(x,b.y);c.lineTo(x-7,b.y+b.h);c.stroke();}}
 else{c.fillStyle=['#969888','#a6a08a','#9e9989','#c1b49a'][kind-3];c.fillRect(b.x,b.y,b.w,b.h);c.fillStyle='#36453e18';for(let k=0;k<4;k++){const x=b.x+(seed*(k+3)%97)/97*b.w,y=b.y+(seed*(k+11)%89)/89*b.h;c.fillRect(x,y,12+seed%30,8+seed%20);}}
 c.strokeStyle='#e2d1ac99';c.lineWidth=5;paintPolygon(c,b.poly);c.stroke();c.strokeStyle='#32403966';c.lineWidth=1;paintPolygon(c,b.poly);c.stroke();
 if(b.w>65&&b.h>65){const x=b.x+b.w*.54,y=b.y+b.h*.48;c.fillStyle='#263b3866';c.fillRect(x+4,y+8,20,22);if(seed%3===0){c.fillStyle='#c7c3aa';c.fillRect(x,y,23,17);c.strokeStyle='#65776a';c.strokeRect(x,y,23,17);c.beginPath();c.arc(x+11,y+8,5,0,TAU);c.stroke();}else{c.fillStyle=seed%2?'#63747a':'#c6bb99';c.fillRect(x,y,17,18);c.beginPath();c.ellipse(x+8.5,y,8.5,4,0,0,TAU);c.fill();c.strokeStyle='#dde0bd88';c.stroke();}
 if(seed%5===0){c.strokeStyle='#304540';c.lineWidth=2;c.beginPath();c.moveTo(x-23,y-10);c.lineTo(x-23,y-41);c.moveTo(x-36,y-31);c.lineTo(x-9,y-31);c.moveTo(x-34,y-38);c.lineTo(x-12,y-38);c.stroke();}
 if(seed%4===0){c.strokeStyle='#36483a';c.lineWidth=1;c.beginPath();c.moveTo(b.x+12,b.y+b.h*.7);c.quadraticCurveTo(b.x+b.w*.5,b.y+b.h*.85,b.x+b.w-10,b.y+b.h*.72);c.stroke();for(let k=0;k<5;k++){c.fillStyle=['#c4b69a','#718e9b','#b17f76','#d5d1b0','#6d7b7c'][k];c.fillRect(b.x+18+k*(b.w-40)/5,b.y+b.h*(.72+.05*Math.sin(k)),7,12+k%3*2);}}
 }
 c.restore();
};
Renderer.prototype.drawUrbanProp=function(c,p){c.save();c.translate(p.x,p.y);c.rotate(p.angle);if(p.type==='bins'){for(let i=0;i<3;i++){c.fillStyle=['#3e5a4f','#718578','#8b826d'][i];c.fillRect(i*12-17,-8,10,16);c.fillStyle='#263b3299';c.fillRect(i*12-18,-9,12,4);}c.fillStyle='#b8ad94';c.fillRect(-23,7,8,5);}
 else if(p.type==='tea'){c.fillStyle='#74644c';c.fillRect(-20,-8,40,16);c.fillStyle='#c6b48b';for(const x of [-14,14]){c.beginPath();c.arc(x,0,6,0,TAU);c.fill();}c.fillStyle='#613e31';for(const x of [-14,14])c.fillRect(x-1,-2,3,4);c.fillStyle='#485d4d';c.fillRect(-18,15,12,6);c.fillRect(6,15,12,6);}
 else if(p.type==='awning'||p.type==='market'){c.fillStyle='#3a423c66';c.fillRect(-23,-13,53,34);for(let i=0;i<6;i++){c.fillStyle=i%2?'#c6b49a':p.type==='market'?'#788b62':'#9c6056';c.fillRect(-24+i*8,-18,8,28);}c.strokeStyle='#495b4d';c.lineWidth=2;c.strokeRect(-24,-18,48,28);c.fillStyle='#665b42';c.fillRect(-19,12,38,9);if(p.type==='market')for(let i=0;i<5;i++){c.fillStyle=i%2?'#bb9e59':'#8f5b46';c.beginPath();c.arc(-14+i*7,16,4,0,TAU);c.fill();}}
 else{c.fillStyle='#92775d';c.fillRect(-17,-8,34,17);for(const x of [-10,0,10]){c.fillStyle='#4e6a49';c.beginPath();c.arc(x,0,8,0,TAU);c.fill();}}c.restore();};
const gridStreetLights=Renderer.prototype.streetLights;
Renderer.prototype.streetLights=function(c,b){if(this.sim.world.mapKind!=='real'){gridStreetLights.call(this,c,b);return;}for(const n of this.sim.world.signals||[]){if(!inScene(n,b,160))continue;const light=c.createRadialGradient(n.x,n.y,3,n.x,n.y,135);light.addColorStop(0,'#f3d39533');light.addColorStop(1,'#f3d39500');c.fillStyle=light;c.fillRect(n.x-135,n.y-135,270,270);}};


Renderer.prototype.drawRealRoads=function(c,b){
 const w=this.sim.world,roads=w.roads.filter(r=>!r.walk&&inScene(r.bounds||{x:r.points[0][1],y:r.points[0][2]},b,r.width+30));
 const trace=road=>{c.beginPath();road.points.forEach((p,i)=>i?c.lineTo(p[1],p[2]):c.moveTo(p[1],p[2]));};
 c.save();c.lineCap=c.lineJoin='round';
 // Foot access is clipped at buildings and at the vehicle carriageway.
 for(const path of w.walkPaths||[]){const p=path.path;if(!p.some(q=>inScene({x:q[0],y:q[1]},b,40)))continue;c.beginPath();p.forEach((q,i)=>i?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1]));c.strokeStyle=path.kind==='pedestrian'?'#9d9b88':'#8c8e7b';c.lineWidth=path.width;c.stroke();if(path.kind==='steps'){c.strokeStyle='#b9b7a044';c.lineWidth=1;for(let i=2;i<p.length;i+=3){const a=p[i-1],q=p[i],dx=q[0]-a[0],dy=q[1]-a[1],len=Math.hypot(dx,dy)||1;c.beginPath();c.moveTo(q[0]-dy/len*5,q[1]+dx/len*5);c.lineTo(q[0]+dy/len*5,q[1]-dx/len*5);c.stroke();}}}
 // Global passes: every curb first, then every gutter, then every asphalt.
 // Never let the edge of one OSM way stripe a crossing OSM way.
 for(const [color,padding] of [['#b0ad98',14],['#596057',3],['#495650',0]]){c.strokeStyle=color;for(const road of roads){c.lineWidth=road.width+padding;trace(road);c.stroke();}}
 c.strokeStyle='#c5c1a766';c.lineWidth=1.6;c.setLineDash([16,25]);
 for(const road of roads){if(road.width<80||/_link$/.test(road.kind))continue;for(let i=1;i<road.points.length;i++){const a=road.points[i-1],z=road.points[i],dx=z[1]-a[1],dy=z[2]-a[2],len=Math.hypot(dx,dy),trimA=w.roadJunctionIds.has(a[0])?road.width*.85:3,trimB=w.roadJunctionIds.has(z[0])?road.width*.85:3;if(len<trimA+trimB+35)continue;c.beginPath();c.moveTo(a[1]+dx/len*trimA,a[2]+dy/len*trimA);c.lineTo(z[1]-dx/len*trimB,z[2]-dy/len*trimB);c.stroke();}}
 c.restore();
};

const classicCoveredPassages=Renderer.prototype.drawCovers;
Renderer.prototype.drawCovers=function(c,b){const w=this.sim.world;if(w.mapKind!=='real'){classicCoveredPassages.call(this,c,b);return;}for(const roof of w.covers){if(!inScene(roof,b,20))continue;c.save();paintPolygon(c,roof.poly);c.fillStyle='#20372b38';c.fill();c.clip();c.translate(roof.center.x,roof.center.y);c.rotate(roof.angle);c.fillStyle='#c1b89a55';for(let x=-64;x<=64;x+=24)c.fillRect(x,-42,5,84);c.restore();c.strokeStyle='#87978288';c.lineWidth=2;paintPolygon(c,roof.poly);c.stroke();}};
